{"summary": "Find 2025 row and nonblank countries in Value/Volume sheets", "security_risk": "LOW", "command": "python3 - <<'PY'
import openpyxl, math
wb=openpyxl.load_workbook('/root/data/test-rar.xlsx', data_only=False)

def find_year_row(ws, year_str='2025'):
    for r in range(1, ws.max_row+1):
        if str(ws.cell(r,1).value).strip()==year_str:
            return r
    return None

for sheet in ['Value','Volume','Total Reserves']:
    ws=wb[sheet]
    yr=find_year_row(ws,'2025')
    print('\n',sheet,'2025 row',yr)
    if yr:
        nonblank=[]
        for c in range(3, ws.max_column+1):
            v=ws.cell(yr,c).value
            if v is None:
                continue
            try:
                if isinstance(v,(int,float)) and (math.isnan(v) if isinstance(v,float) else False):
                    continue
            except Exception:
                pass
            # treat 0 as data? likely 0 means no gold; but still data. We'll include non-None.
            header=ws.cell(1,c).value
            nonblank.append((c,header,v))
        print('nonblank count',len(nonblank))
        for c,header,v in nonblank[:20]:
            print(' ',c, header.split(':')[0] if isinstance(header,str) else header, v)
PY"}

